CSS='''
.bk{--ink:#16343b;--copper:#ab5033;background:#f6f3ed;color:var(--ink);padding-bottom:70px;font-family:Montserrat,Arial,sans-serif}.bk *{box-sizing:border-box}.bk-hero{background:#0b252c;color:#fff;padding:65px max(24px,calc((100vw - 1180px)/2)) 85px}.bk-kicker{font-size:11px;font-weight:800;letter-spacing:.17em;text-transform:uppercase;color:#c9896a}.bk h1{font:500 clamp(54px,6vw,88px)/1.04 'Cormorant Garamond',Georgia,serif;margin:22px 0}.bk h1 em{color:#e0aa90}.bk-hero p{max-width:650px;line-height:1.9;color:#c4d0d1;font-size:15px}.bk-shell{max-width:1180px;margin:-24px auto 0;padding:0 22px;position:relative}.bk-progress{display:flex;justify-content:space-between;background:#fff;border:1px solid #e5dfd4;border-radius:12px;padding:22px 26px;gap:16px;margin-bottom:30px;font-size:12px;font-weight:700}.bk-progress b{color:var(--copper);margin-inline-end:10px}.bk-layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:30px;align-items:start}.bk-panel{background:white;border:1px solid #e3ddd2;border-radius:14px;padding:30px;margin-bottom:22px}.bk h2{font:600 36px/1.2 'Cormorant Garamond',Georgia,serif;margin:12px 0 24px}.bk-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.bk label.bk-field{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:700}.bk input:not([type=checkbox]),.bk select,.bk textarea{width:100%;min-width:0;border:1px solid #c9cec9;border-radius:7px;background:#fff;padding:13px;color:#16343b;font:inherit;min-height:46px}.bk input:focus-visible,.bk select:focus-visible,.bk textarea:focus-visible{outline:2px solid #ab5033;outline-offset:2px}.bk-full{grid-column:1/-1}.bk-stays,.bk-choices{display:grid;gap:10px}.bk-choice{display:flex;align-items:flex-start;gap:12px;border:1px solid #dce1dc;border-radius:8px;padding:16px;cursor:pointer;line-height:1.6;font-size:13px}.bk-choice:has(input:checked){border-color:#ab5033;background:#fbf1e9}.bk-choice input{accent-color:#ab5033;margin-top:4px;width:17px;height:17px;flex-shrink:0}.bk-choice strong{font-weight:700}.bk-choice small{display:block;color:#687779;font-size:11px;margin-top:4px}.bk-note{font-size:12px;line-height:1.8;color:#657477;margin:18px 0 0}.bk-alert{border-inline-start:3px solid #b4603e;padding:12px 15px;background:#faf3e9}.bk-summary{position:sticky;top:95px;background:#10313a;color:white;border-radius:14px;padding:26px}.bk-summary h2{font-size:32px}.bk-summary ul{list-style:none;padding:0;margin:20px 0}.bk-summary li{padding:13px 0;border-bottom:1px solid #ffffff26;font-size:12px;line-height:1.8}.bk-total{font:500 48px/1.3 'Cormorant Garamond',Georgia,serif;margin:10px 0}.bk-summary p{font-size:11px;line-height:1.8;color:#c0cece}.bk-send{display:block;width:100%;padding:17px;background:#bd643f;color:white;border:0;border-radius:7px;font:700 13px Montserrat,Arial,sans-serif;cursor:pointer;margin-top:22px}.bk-error{color:#a42d20;font-size:13px;line-height:1.6}.bk-summary .bk-quote{color:#edbd9d}.bk[dir=rtl],.bk[dir=rtl] h1,.bk[dir=rtl] h2,.bk[dir=rtl] .bk-total{font-family:Tajawal,Arial,sans-serif}.bk[dir=rtl] h1{line-height:1.3}.bk[dir=rtl] input[type=date],.bk[dir=rtl] input[type=tel]{direction:ltr;text-align:right}@media(max-width:850px){.bk-layout{grid-template-columns:1fr}.bk-summary{position:static}.bk-hero{padding:42px 24px 65px}.bk-panel{padding:23px}.bk-progress{padding:19px 16px;font-size:10px}.bk-shell{padding:0 15px}.bk-fields{gap:15px}.bk h2{font-size:31px}}@media(max-width:460px){.bk-fields{grid-template-columns:1fr}.bk-progress b{display:block;margin-bottom:6px}.bk h1{font-size:57px}}'''
JS='''(function(){
const root=document.getElementById('bookingNew');if(!root)return;
const t=JSON.parse(document.getElementById('bookingWords').textContent),form=document.getElementById('bookingForm');
const $=id=>document.getElementById(id),today=new Date();
const date=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');$('arrival').min=date;$('departure').min=date;
const services=JSON.parse(document.getElementById('bookingServices').textContent);
function calculate(){
 const people=Number($('guests').value)||1,start=$('arrival').value,end=$('departure').value;
 const nights=start&&end?Math.round((Date.parse(end)-Date.parse(start))/86400000):1;
 const lines=[];let total=0,quotes=false;
 const stay=$('stay').value;$('departure').required=stay!=='none';
 function add(name,amount,detail){lines.push({name,amount,detail});if(amount===null)quotes=true;else total+=amount;}
 if(stay==='house')add(t[19],300*Math.max(nights,1),'300 × '+Math.max(nights,1)+' '+t[33]);
 if(stay==='gite250')add(t[21],250*people*Math.max(nights,1),'250 × '+people+' × '+Math.max(nights,1)+' '+t[33]);
 if(stay==='gite350')add(t[23],nights===1?350*people:null,t[24]+(nights!==1?' · '+t[30]:''));
 if(stay==='weekend')add(t[25],null,t[26]);
 form.querySelectorAll('[data-service]:checked').forEach(input=>{const a=services.find(a=>a.id===input.value);let qty=a.unit==='person'?people:a.unit==='duo'?Math.ceil(people/2):a.unit==='quad'?people:1;add(a.name,a.price===null?null:a.price*qty,a.price===null?t[30]:a.price+' × '+qty);});
 $('summaryList').replaceChildren();lines.forEach(a=>{const li=document.createElement('li'),strong=document.createElement('strong'),small=document.createElement('div');strong.textContent=a.name;small.textContent=a.detail+' · '+(a.amount===null?t[30]:a.amount+' DH');li.append(strong,small);$('summaryList').append(li)});
 $('emptySummary').hidden=lines.length>0;$('total').textContent=total.toLocaleString()+' DH';$('quoteNote').hidden=!quotes;
 $('campNote').hidden=!form.querySelector('[value="camping"]:checked');$('raftNote').hidden=!form.querySelector('[value^="raft"]:checked');
 return {people,nights,lines,total,quotes,stay};
}
form.addEventListener('input',calculate);form.addEventListener('change',calculate);
form.addEventListener('submit',e=>{
 e.preventDefault();const c=calculate();$('bookingError').textContent='';
 if(!form.reportValidity())return;
 if(!c.lines.length){$('bookingError').textContent=t[36];return;}
 if(c.stay!=='none'&&(!Number.isInteger(c.nights)||c.nights<1||c.nights>45)){$('bookingError').textContent=t[37];return;}
 if(form.querySelector('[value="camping"]:checked')&&c.people<10){$('bookingError').textContent=t[38];return;}
 if($('arrival').value<date){$('arrival').focus();return;}
 const msg=['IMSFRANE · '+t[6],t[10]+': '+$('name').value,t[11]+': '+$('phone').value,t[12]+': '+$('email').value,t[8]+': '+$('arrival').value,t[9]+': '+$('departure').value,t[7]+': '+c.people,'',t[56]+':',...c.lines.map(a=>'- '+a.name+' | '+a.detail+' | '+(a.amount===null?t[30]:a.amount+' DH')),'',t[28]+': '+c.total+' DH'+(c.quotes?' + '+t[40]:''),t[13]+': '+$('notes').value,t[35]].join('\\n');
 window.open('https://wa.me/212667772551?text='+encodeURIComponent(msg),'_blank','noopener');
});calculate();
})();'''
def build(root):
 base='/Imsfrane-demo/'
 (root/'booking-new.css').write_text(CSS);(root/'booking-new.js').write_text(JS)
 for lang,t in D.items():
  # Keep unconfirmed rafting prices on request; keep current validated fixed rates.
  services=[('raft12',44,400,'person'),('raft30',45,None,'person'),('raft50',46,None,'person'),('raft4',60,None,'person'),('hikeSummit',48,300,'group'),('hikeGorges',49,200,'group'),('hikeGrand',50,400,'group'),('vtt',51,150,'person'),('quadSolo',52,250,'quad'),('quadDuo',53,300,'duo'),('camping',54,None,'group'),('transport',41,None,'group'),('kayak',42,None,'group'),('custom',43,None,'group')]
  catalog=[dict(id=id,name=t[i],price=price,unit=unit) for id,i,price,unit in services]
  choices=''
  for a in catalog:
   unit=t[31] if a['unit']=='person' else t[32] if a['unit']=='group' else 'Quad'
   price=t[30] if a['price'] is None else f'{a["price"]} DH / {unit}'
   desc=t[47] if a['id']=='raft50' else ''
   choices+=f'<label class="bk-choice"><input type="checkbox" data-service value="{a["id"]}"><span><strong>{a["name"]}</strong><small>{price} {desc}</small></span></label>'
  opts=[('none',18,''),('house',19,20),('gite250',21,22),('gite350',23,24),('weekend',25,26)]
  options=''.join(f'<option value="{v}">{t[i]}</option>' for v,i,_ in opts)
  stays=''.join(f'<p class="bk-note"><strong>{t[i]}</strong><br>{t[d]}</p>' for _,i,d in opts if d)
  main=f'''<main id="mainContent"><div class="bk" id="bookingNew" dir="{'rtl' if lang=='ar' else 'ltr'}"><section class="bk-hero"><div class="bk-kicker">IMSFRANE · {t[3]}</div><h1>{t[0]}<br><em>{t[1]}</em></h1><p>{t[2]}</p></section><div class="bk-shell"><nav class="bk-progress" aria-label="{t[3]}"><span><b>01</b>{t[4]}</span><span><b>02</b>{t[5]}</span><span><b>03</b>{t[6]}</span></nav><form id="bookingForm"><div class="bk-layout"><div><section class="bk-panel"><div class="bk-kicker">01 · {t[5]}</div><h2>{t[5]}</h2><div class="bk-fields"><label class="bk-field">{t[7]}<input id="guests" type="number" min="1" max="60" step="1" value="2" required inputmode="numeric"></label><label class="bk-field">{t[8]}<input id="arrival" type="date" required></label><label class="bk-field">{t[9]}<input id="departure" type="date"></label><label class="bk-field">{t[15]}<select id="stay">{options}</select></label></div>{stays}</section><section class="bk-panel"><div class="bk-kicker">02 · {t[4]}</div><h2>{t[16]}</h2><div class="bk-choices">{choices}</div><p class="bk-note bk-alert" id="raftNote" hidden>{t[39]}</p><p class="bk-note bk-alert" id="campNote" hidden>{t[38]}</p></section><section class="bk-panel"><div class="bk-kicker">03 · {t[6]}</div><h2>{t[6]}</h2><div class="bk-fields"><label class="bk-field">{t[10]}<input id="name" autocomplete="name" maxlength="90" required></label><label class="bk-field">{t[11]}<input id="phone" type="tel" autocomplete="tel" minlength="6" maxlength="30" required></label><label class="bk-field bk-full">{t[12]}<input id="email" type="email" autocomplete="email" maxlength="120"></label><label class="bk-field bk-full">{t[13]}<textarea id="notes" rows="4" maxlength="2000" placeholder="{t[14]}"></textarea></label></div><p id="bookingError" class="bk-error" role="alert"></p></section></div><aside class="bk-summary"><div class="bk-kicker">IMSFRANE · ATLAS</div><h2>{t[27]}</h2><p id="emptySummary">{t[34]}</p><ul id="summaryList" aria-live="polite"></ul><p>{t[28]}</p><div class="bk-total" id="total">0 DH</div><p class="bk-quote" id="quoteNote" hidden>+ {t[40]}</p><p>{t[35]}</p><button type="submit" class="bk-send">{t[29]} ↗</button><p>{t[55]}</p></aside></div></form></div></div></main>'''
  page=root/lang/'booking/index.html';html=page.read_text()
  html=re.sub(r'<main\b[^>]*>.*?</main>',lambda _:main,html,count=1,flags=re.S)
  html=re.sub(r'<script[^>]*src="[^"]*(?:booking-pro.js|pages/booking.min.js)[^"]*"[^>]*></script>','',html)
  html=re.sub(r'<script[^>]*id="bpCatalog"[^>]*>.*?</script>','',html,flags=re.S)
  html=re.sub(r'<title\b[^>]*>.*?</title>',f'<title>{t[3]} | Imsfrane Cathédrale</title>',html,flags=re.S)
  html=html.replace('</head>',f'<link rel="stylesheet" href="{base}booking-new.css?v=1"><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600&family=Montserrat:wght@400;500;600;700;800&family=Tajawal:wght@400;700&display=swap" rel="stylesheet"></head>')
  html=html.replace('</body>',f'<script id="bookingWords" type="application/json">{json.dumps(t,ensure_ascii=False)}</script><script id="bookingServices" type="application/json">{json.dumps(catalog,ensure_ascii=False)}</script><script defer src="{base}booking-new.js?v=1"></script></body>')
  page.write_text(html);(root/lang/'booking.html').write_text(html)
 print('Built current demo booking in FR EN ES AR')
if __name__=='__main__':
 import sys
 build(Path(sys.argv[1] if len(sys.argv)>1 else 'public'))
